'use strict';
// Documents 00 and 02-13. v2.
const H = require('./helpers.js');
const { CO, CO_UP, FORMED, DEFILE, EIN, RA, ADDR, TALENT_DATE, REDEMPTION_DATE, BANK, AUTH_UNITS, RESERVE, VP, DVP, HIST, HIST_TOTAL, CONTRIB, SERVICE, CONTRIB_EACH, APPROX_TOTAL, APPROX_EACH, FOUNDERS, BROCK, CLASS_A, CLASS_B, OUTSTANDING, CEO, CTO, JGN_MEMBERS, N_FOUNDERS, RUPIA_FIRST, BROCK_DOC, TALENT_AMEND_DOC, RECEIPT_FIRST, RECEIPT_LAST, money, num, fdPct, outPct, votePct, vested, monthly, nbName, listAnd, FOUNDERS_AND, JGN_AND, doc, EFF, DEF_ONLY, DEFINED, kv, tbl, coSig, personSig, memberSigs } = H;

const CAP_HEAD = ['Member', 'Class and office', 'Units', 'Fully diluted %', 'Consideration', 'Immediately vested', 'Restricted over 48 months'];
function capTable() {
  const rows = FOUNDERS.map(f => [nbName(f), 'Class A; ' + f.office, num(f.units), fdPct(f.units), f.jgn ? 'Capital Contribution through JGN, ' + APPROX_EACH : 'Services; profits interest', num(vested(f)), num(vested(f))]);
  rows.push([nbName(BROCK), 'Class B; Co-Founder', num(BROCK.units), fdPct(BROCK.units), 'Services under the Talent Agreement; profits interest', num(BROCK.units), 'None']);
  rows.push(['Reserved Units', 'Unissued (Operating Agreement Section 3.13)', num(RESERVE), fdPct(RESERVE), '', '', '']);
  rows.push(['<strong>Total authorized</strong>', '', '<strong>' + num(AUTH_UNITS) + '</strong>', '<strong>100%</strong>', '<strong>' + APPROX_TOTAL + '</strong>', '<strong>' + num(CLASS_A / 2 + CLASS_B) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>']);
  return tbl(CAP_HEAD, rows, 'cap keep', H.CAP_COLS);
}
const CONTRIB_AND = listAnd(CONTRIB.map(f => f.name));
const OWN_SUMMARY = `${FOUNDERS.map(f => fdPct(f.units)).join(' / ')} / ${fdPct(BROCK.units)} across six Members on a fully diluted basis, with ${fdPct(RESERVE)} reserved and unissued`;
const CREDIT_FROM = 'JGN Contribution paid by JGN Media LLC on behalf of its four members, one quarter each (Operating Agreement Sections 3.4, 3.5 and 3.9)';

// 00 Master Record Book Index
function doc00() {
  const body = EFF +
  `<p>This record book documents the issuance of ${num(CLASS_A)} restricted Class A Units to the five Founders: to the four Contributing Founders in exchange for their Capital Contributions, made through JGN Media LLC, which paid every expense of the Company and the Platform (${APPROX_TOTAL} in total, ${APPROX_EACH} each), and to the Service Founder, ${SERVICE.name}, for his services. No Founder purchases Units for cash. It also documents the issuance of ${num(CLASS_B)} fully vested Class B Units to Brock Smith under the Talent Agreement and the reservation of ${num(RESERVE)} unissued Units for future strategic partners and Milestone Units, and records the agreed ownership, governance, vesting, IP ownership, the JGN arrangements (assignment of the Platform, the Brand License, promotion through the Social Accounts and continued funding), transfer restrictions, restrictive covenants and the historical operating expenses.</p>
  <h2>1. CAPITALIZATION AND ISSUANCE TERMS</h2>` + capTable() +
  kv([['Authorized Units', num(AUTH_UNITS)], ['Issued Class A Units', num(CLASS_A)], ['Issued Class B Units', num(CLASS_B)], ['Outstanding Units', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)], ['Fully diluted ownership', '100%'],
    ['Total company equity FMV', APPROX_TOTAL + ', equal to the aggregate JGN Contribution through the Actual Closing Date'], ['Aggregate Founder Capital Contributions', APPROX_TOTAL], ['Capital Contribution of each Contributing Founder', APPROX_EACH], ['Aggregate capital credited to Members\' Capital Accounts', APPROX_TOTAL], ['Cash paid for Units', 'None'],
    ['Interest type', 'Contributing Founders: restricted Class A Units issued for Capital Contributions. Service Founder and Class B Member: profits interests issued for services.'], ['Vesting', 'Class A: 50% immediately vested; 50% monthly over 48 months; 100% if a buyer ends the Founder\'s service. Class B: fully vested on issuance.'], ['Transfer Date', 'Actual Closing Date']]) +
  `<h2>2. COMPANY IDENTIFIERS OF RECORD</h2>` +
  kv([['Legal name', CO], ['Jurisdiction', 'Delaware limited liability company'], ['Date of formation', FORMED], ['Delaware file number', DEFILE], ['Federal employer identification number (EIN)', EIN], ['Registered agent', RA], ['Principal business office', ADDR], ['Company bank accounts', 'None on the date this record book was prepared; a business checking account in the Company\'s legal name is to be opened at Chase under the Banking Resolution and recorded in the Company Account Schedule']]) +
  `<h2>3. DOCUMENTS INCLUDED IN THIS RECORD BOOK</h2>` +
  tbl(['No.', 'Document', 'Purpose'], [
    ['00', 'Master Record Book Index', 'Record-book index and closing record.'],
    ['01', 'Operating Agreement', 'Primary Company governance, ownership, voting, transfer, vesting, capital-account, Service Unit, Reserved Unit, IP/account, JGN and approval-threshold instrument.'],
    ['02', 'Initial Member and Organizational Written Consent', 'Approves FMV, the Capital Contributions, the equity issuances, updated records and supporting documents.'],
    ['03', 'Founder Equity Fair Market Value Determination Memorandum', 'Good-faith FMV support for the issuance and for the profits-interest treatment of the Service Units, including completed factual worksheet and launch-stage valuation rationale.'],
    ['04', 'Founder Capital Contribution Instructions', 'How each Contributing Founder\'s Capital Contribution is recorded; no cash, notes or deferred-payment rights.'],
    ['05', 'Aggregate Founder Issuance Closing Statement', 'Reconciles all Units, Capital Contributions and issuance conditions.'],
    ['06', 'Founder Capital Contribution Ledger', 'Records each Capital Contribution and the accounting fields.'],
    ['07', 'Company Officer Certificate – Founder Equity Closing', 'Officer certification of contributions, issuance and record updates.'],
    ['08', 'Officer Appointment Record and Authority Certificate', 'Officer titles, lanes and spending authority as delegated under the Operating Agreement.'],
    ['09', 'Banking Resolution', 'Opening of the Company bank account, authorized signer and account controls.'],
    ['10', 'Official Unit Ledger', 'Register of issued Units by Member and class, with entry numbers, and of the Reserved Units.'],
    ['11', 'Capitalization Table', 'Outstanding and fully diluted ownership by Member, Units, percentages and consideration.'],
    ['12', 'Founder Equity and Vesting Ledger', 'Vested and restricted Units, vesting schedule and repurchase terms for each Founder; Class B reference.'],
    ['13', 'Founder Contribution and Separation Schedule', 'Per-Member record separating Capital Contributions, services, IP and other items.'],
    ['14', 'Historical Company Operating Expense and JGN Contribution Schedule', 'Record of historical operating expenses by item, amount and payer, and their treatment as the Contributing Founders\' Capital Contributions.'],
    ['15', 'Company Asset Schedule', 'Categories of Company-owned software, data, account and record assets, and of the JGN-owned Brand and Social Accounts.'],
    ['16', 'IP Assignment Schedule and Chain of Title Register', 'Chain of title for each category of Company IP and the documents that establish it.'],
    ['17', 'Company Account Schedule', 'Company-critical account categories and control standard.'],
    ['18', 'Founder Proprietary Information, IP Assignment and Data Security Agreement (Founder PIIA)', 'Founder confidentiality, invention assignment, data-security and account-control obligations.'],
    ['19', 'JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement (JGN Agreement)', 'Entity-level assignment of the Platform Assets from JGN, the Brand License, the promotion covenant, JGN Contributions, revenue allocation and account transition.'],
    ['20', 'JGN Member Consent Approving Nosebleed Agreement', 'JGN member approval of the JGN Agreement and the JGN Contribution, and authority for its signatory.'],
    ['21', 'Closing Checklist and Signature Index', 'Execution sequence and signatory matrix.'],
    ['22', 'Organization and Governance Summary', 'Record-book summary of member-managed structure, officer lanes and the JGN relationship.'],
    ['23', 'Capitalization Reconciliation Report', 'Reconciliation of Units, percentages, FMV, Capital Contributions, Capital Accounts, Service Units, Reserved Units and vesting.'],
    ['24', 'Record Book Certification', 'Company certification of what this record book contains on capitalization, chain of title, records, JGN authority and expenses.'],
    [`${RUPIA_FIRST}–${RUPIA_FIRST + N_FOUNDERS - 1}`, 'Founder Restricted Unit Issuance Agreements', 'Individual Founder issuance, vesting, tax-responsibility, securities and continuing-obligation documents.'],
    [String(BROCK_DOC), 'Brock Smith Class B Unit Issuance Record', 'Company record of the Class B issuance to Brock Smith under the Talent Agreement; signed by the Company only.'],
    [String(TALENT_AMEND_DOC), 'First Amendment to Talent, Handicapping, and Content Services Agreement', 'Sets Brock Smith\'s Initial Units at 150,000 fully vested Class B Units, restates his milestones to the same 5% cap, and contains his joinder to the Operating Agreement.'],
    [`${RECEIPT_FIRST}–${RECEIPT_LAST}`, 'Founder Capital Contribution Receipts', 'Receipts completed once each Contributing Founder\'s Capital Contribution is recorded.'],
  ]) +
  `<h2>4. CLOSING RECORD</h2>` +
  kv([
    ['Ownership', OWN_SUMMARY + '.'],
    ['Voting thresholds', `Every Member approval requires affirmative written votes of Members holding at least ${VP} of outstanding Class A Units (Section 5.2), which on the initial capitalization means any four of the five Founders. A Change of Control, any issuance of equity, any amendment of the Operating Agreement and any change of the Chief Executive Officer also require the consent of ${CEO.name} while he is in Continuous Service (Section 5.7). Class B Units and Reserved Units do not vote. Where the Operating Agreement measures a vote by Disinterested Ownership (matters about one Member, such as Cause, Disability and the Company's purchase rights), approval requires at least three disinterested Members holding at least ${DVP} of the Disinterested Ownership, which on the initial capitalization means any three of the other four Founders, subject to Section 5.2 where fewer than three Members are disinterested. Non-response never counts as approval.`],
    ['Units', `${num(AUTH_UNITS)} authorized; ${num(CLASS_A)} Class A Units and ${num(CLASS_B)} Class B Units issued after the Founder closing (${num(OUTSTANDING)} outstanding); ${num(RESERVE)} Reserved Units unissued.`],
    ['Total equity FMV', `${APPROX_TOTAL}, equal to the aggregate JGN Contribution, subject to reconsideration before the Units are issued if undisclosed Valuation Date facts exist.`],
    ['Capital Contributions', `${APPROX_TOTAL} in aggregate, made by the four Contributing Founders through JGN, ${APPROX_EACH} each (${money(HIST_TOTAL)} ÷ 4 = ${money(CONTRIB_EACH)}). The Service Founder and the Class B Member make none.`],
    ['Capital Account credit', `${APPROX_TOTAL} in aggregate, equal to the aggregate Capital Contributions. The opening Capital Accounts of the Service Founder and the Class B Member are zero.`],
    ['No cash purchase', 'No Founder pays cash, gives a note or owes a purchase price for Units.'],
    ['Distributions', 'Every distribution, including sale proceeds, first returns Unreturned Capital to the Contributing Founders, without interest, and is then shared by all outstanding Units pro rata (Operating Agreement Section 10.5).'],
    ['Vesting', 'Class A: 50% immediately vested and 50% monthly over 48 months for each Founder; 100% of unvested Units vest if a buyer ends the Founder\'s service without Cause, the Founder resigns for Good Reason, the buyer does not keep the Founder on, or the Founder dies or has a Disability after the sale (Operating Agreement Section 6.12). Class B: fully vested on issuance.'],
    ['Service Units', `${SERVICE.name}'s ${num(SERVICE.units)} Class A Units and Brock Smith's ${num(CLASS_B)} Class B Units are issued for services as profits interests, with no Capital Contribution and no liquidation value on the Valuation Date.`],
    ['Class B issuance', `${num(CLASS_B)} Class B Units are issued to Brock Smith on the Actual Closing Date as the Initial Units under Section 5.1 of the Talent Agreement, as amended by the Talent Amendment (document ${TALENT_AMEND_DOC}), fully vested. Milestone Units, if earned, are issued from the Reserved Units up to a cumulative 5% fully diluted interest.`],
    ['Reserved Units', `${num(RESERVE)} authorized Units (${fdPct(RESERVE)} fully diluted) are reserved for future strategic partners, issuable only as a Major Decision with the consent required by Section 5.7, and for Milestone Units under the Talent Agreement, for which 350,000 are set aside (Operating Agreement Section 3.13).`],
    ['Transfer Date', 'The Transfer Date is the Actual Closing Date (Operating Agreement Section 2.8).'],
    ['IP chain of title', 'Founder PIIA, JGN Agreement, JGN Member Consent, Talent Agreement, Company Account Schedule and IP Assignment Schedule and Chain of Title Register are included in or referenced by this record book.'],
    ['Brand and Social Accounts', 'The Nosebleed Sports brand and the Social Accounts are owned by JGN. The Company uses the brand under the exclusive, perpetual, royalty-free, transferable Brand License in the JGN Agreement and the Platform is promoted through the Social Accounts under the promotion covenant there.'],
    ['Commercial status', 'The FMV memorandum records the Company as launch-stage: the Platform was built with JGN funding, has generated no revenue, the Company has no bank account as of the date the memorandum was prepared, and the Company has no outside financing and no bona fide third-party equity or acquisition offers as of the Valuation Date. All revenue of the Nosebleed Sports brand to date came from the Social Accounts and belongs to JGN.'],
    ['Historical expenses and JGN funding', `Operating Agreement Schedule C, the Founder Contribution and Separation Schedule and the Historical Company Operating Expense and JGN Contribution Schedule record that JGN paid every historical operating expense, ${APPROX_TOTAL} from May through November 2026. That amount is the Capital Contribution of the four Contributing Founders. It is not a loan, and no Member owes any share of it.`],
    ['JGN ownership and authority', `JGN Media LLC is owned 25% each by ${JGN_AND}. ${CEO.name} signs the JGN Agreement and the First Amendment to the Talent Agreement for JGN as its Chief Executive Officer and for the Company as its Chief Executive Officer, each as authorized by the unanimous JGN Member Consent and the unanimous Initial Member and Organizational Written Consent.`],
    ['Entity', 'Member-managed Delaware limited liability company.'],
  ]) + coSig('Certified by the Company at closing');
  return doc(0, 'MASTER RECORD BOOK INDEX', body);
}

// 02 Initial Member and Organizational Written Consent
function doc02() {
  const body = `<p><strong>Effective date:</strong> the Unit issuances authorized by this consent occur only on the Actual Closing Date, after all required signatures are delivered and each Contributing Founder's Capital Contribution is recorded, as stated in Resolution 3. Under Section 2.8 of the Operating Agreement, the Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date are the same date unless the Operating Agreement is amended under Article 16 to provide otherwise. ${DEFINED}</p>
<p>The undersigned, constituting all initial Class A Members of ${CO}, adopt the following resolutions by unanimous written consent, effective upon signature by all Class A Members.</p>
<h2>RECITALS</h2>
<p>A. The Company was formed as a Delaware limited liability company on ${FORMED} (Delaware file number ${DEFILE}) by ${CEO.name} as authorized person, and was assigned EIN ${EIN} on August 17, 2026.</p>
<p>B. JGN Media LLC, whose four members are the Contributing Founders, paid every expense of the Company and the Platform through the Actual Closing Date. The Members desire to complete the Company's Founder closing, documented in this record book, by issuing restricted Class A Units to the Contributing Founders for that Capital Contribution and to the Service Founder for his services, and Class B Units to Brock Smith under the Talent Agreement. No Founder purchases Units for cash.</p>
<p>C. The Founder closing occurs on the Actual Closing Date, when all required signatures are delivered and the Capital Contributions are recorded; that date is the Transfer Date.</p>
<p>D. Before this consent, the Company had no written limited liability company agreement. The only agreement promising an interest in the Company is the Talent Agreement dated as of ${TALENT_DATE} among JGN Media LLC, the Company and Brock Smith, which Section 3.7(b) of the Operating Agreement performs.</p>
<h2>RESOLUTIONS</h2>
<p>1. Adoption of Operating Agreement. The Limited Liability Company Agreement of the Company, in the form included in this record book as Document 01, is approved and adopted effective as of the Actual Closing Date. By this consent, the Company is bound by the Sections of the Operating Agreement listed in its Section 2.8 from the date each Founder signs, whether or not the Company's signature block has then been signed. The adoption satisfies Section 5.6 of the Talent Agreement.</p>
<p>2. FMV Determination. The Members approve a total company equity Fair Market Value as of the Transfer Date equal to the aggregate JGN Contribution through that date, ${APPROX_TOTAL}, supported by the Founder Equity Fair Market Value Determination Memorandum.</p>
<p>3. Issuance of Units. The Company is authorized to issue ${num(CLASS_A)} Class A Units to the Founders in the amounts and percentages shown in the table following Resolution 13, conditioned on execution of required documents and the recording of each Contributing Founder's Capital Contribution, and ${num(CLASS_B)} Class B Units to Brock Smith on the Actual Closing Date under Section 3.7(b) of the Operating Agreement and the Talent Amendment. ${num(RESERVE)} authorized Units remain unissued as Reserved Units.</p>
<p>4. Founder Capital Contributions. The JGN Contribution through the Actual Closing Date, ${APPROX_TOTAL}, is accepted as the Capital Contribution of the four Contributing Founders, ${APPROX_EACH} each, made through JGN, in exchange for their Class A Units. The Service Founder receives his Class A Units for services under Section 3.7(a) of the Operating Agreement and makes no Capital Contribution.</p>
<p>5. No Cash Purchase. No Founder pays cash, gives a note or owes a purchase price or deferred payment for Units. Once the Actual Closing Date occurs, a recorded Capital Contribution may not be reduced, refunded, offset or recharacterized except as the Operating Agreement provides; if the Actual Closing Date has not occurred within 120 days after the first Founder signs the Operating Agreement, as its Section 3.6 provides, the recorded contributions lapse and no Units are issued.</p>
<p>6. Capital Account Treatment. The Capital Contributions shall be credited to the Contributing Founders' Capital Accounts in the aggregate amount of ${APPROX_TOTAL}. The opening Capital Accounts of the Service Founder and the Class B Member are zero.</p>
<p>7. Separate Founder Obligations. IP assignments, confidentiality, data-security, service, vesting, restrictive-covenant and acquisition-cooperation obligations are approved and remain separate from the Capital Contributions.</p>
<p>8. Restricted Unit Agreements, Class B Record and Talent Amendment. The Members approve the founder-specific Restricted Unit Issuance Agreements, the Brock Smith Class B Unit Issuance Record and the First Amendment to the Talent Agreement, and authorize the Company to execute them.</p>
<p>9. Contribution Recording Process. The Chief Executive Officer is authorized to compile the JGN Contribution from JGN's payment records, make those records available to every Member, record each Capital Contribution, issue receipts, and update the Company's books, the Founder Capital Contribution Ledger, the Members' Capital Accounts, the Official Unit Ledger, the Capitalization Table, the Founder Equity and Vesting Ledger and the Company's tax records.</p>
<p>10. Founder PIIA and JGN Documents. The Members approve the Founder Proprietary Information, IP Assignment and Data Security Agreement (the Founder PIIA), the JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement (the JGN Agreement) and the JGN Member Consent Approving Nosebleed Agreement, approve the JGN Agreement as a Major Decision under Schedule B of the Operating Agreement after the disclosure in Schedule D, authorize ${CEO.name}, Chief Executive Officer, to execute the JGN Agreement and the First Amendment to the Talent Agreement on behalf of the Company although he also signs each of them for JGN, and authorize execution and record-book retention of those documents.</p>
<p>11. Officers and Banking. The Members approve the Officer Appointment Record and Authority Certificate and the Banking Resolution, provided they do not expand authority beyond the Operating Agreement. The officer appointments and banking authority they record are effective upon signature of this consent and continue in effect under the Operating Agreement on and after the Actual Closing Date. Until the Actual Closing Date, Sections 4.2, 4.3 and 4.8 of the Operating Agreement apply to them as if that Agreement were in effect.</p>
<p>12. Record-Book Documents. The Members approve the following record-book documents as Company records: Master Record Book Index, Company Officer Certificate – Founder Equity Closing, Founder Equity Fair Market Value Determination Memorandum, Founder Capital Contribution Instructions, Aggregate Founder Issuance Closing Statement, Founder Capital Contribution Ledger, Founder Capital Contribution Receipts, Official Unit Ledger, Capitalization Table, Founder Equity and Vesting Ledger, Founder Contribution and Separation Schedule, Historical Company Operating Expense and JGN Contribution Schedule, Company Asset Schedule, IP Assignment Schedule and Chain of Title Register, Company Account Schedule, Closing Checklist and Signature Index, Organization and Governance Summary, Capitalization Reconciliation Report and Record Book Certification.</p>
<p>13. Omnibus Authority. Each officer is authorized to take lawful actions and sign documents reasonably necessary to implement these resolutions, maintain Company records and preserve acquisition-readiness documentation, subject to the Operating Agreement.</p>` +
  capTable() + `<h2>MEMBER SIGNATURES</h2>` + memberSigs(() => 'Class A Member');
  return doc(2, 'INITIAL MEMBER AND ORGANIZATIONAL WRITTEN CONSENT', body);
}

// 03 FMV Memorandum
function doc03() {
  const body = `<p><strong>Effective date:</strong> this memorandum speaks as of the Valuation Date and is dated as of the Actual Closing Date. The Members approve it before any Units are issued and reconsider it before closing if any undisclosed Valuation Date fact exists. Under Section 2.8 of the Operating Agreement, the Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date are the same date unless the Operating Agreement is amended under Article 16 to provide otherwise. ${DEFINED}</p>` +
  kv([['Company', CO], ['Entity type', 'Delaware limited liability company'], ['Valuation Date', 'Actual Closing Date (the "Valuation Date")'], ['Purpose', `Support the issuance of ${num(CLASS_A)} Class A Units and ${num(CLASS_B)} Class B Units, and the treatment of the Service Units as profits interests.`], ['Total company equity FMV', APPROX_TOTAL + ', equal to the aggregate JGN Contribution through the Valuation Date'], ['Method', 'Cost: the documented amounts paid to form the Company and build the Platform'], ['Liquidation value of the Service Units on the Valuation Date', 'None; Unreturned Capital of ' + APPROX_TOTAL + ' is returned first under Operating Agreement Section 10.5'], ['Not an appraisal', 'This memorandum is not an independent appraisal, certified valuation, fairness opinion, formal tax opinion or approval by a tax authority.']]) +
  `<h2>1. VALUATION STANDARD AND SCOPE</h2>
<p>The Members determined in good faith that the total equity Fair Market Value of the Company as of the Valuation Date equals the aggregate JGN Contribution through that date, ${APPROX_TOTAL}: the documented cost of the Company's formation and of building the Platform. This determination is intended to reflect the Company's actual facts as of the Transfer Date, not gross enterprise value, future projections, aspirational value, the value of the Nosebleed Sports brand or media audience (which the Company does not own), possible strategic value, or later financing or acquisition value.</p>
<p>Future financing, revenue, product development, commercial success, subscriber traction, third-party offers or acquisition value does not retroactively change the good-faith FMV as of the Valuation Date.</p>
<h2>2. FACTUAL VALUATION WORKSHEET</h2>` +
  tbl(['Valuation factor', 'Company factual input', 'Valuation relevance'], [
    ['Cash and cash equivalents', 'None. The Company had no bank account as of the date this memorandum was prepared, no Founder pays cash for Units, and every Company expense to date has been paid by JGN outside any Company account.', 'Cash directly affects equity value.'],
    ['Accounts receivable', 'None. The Platform has generated no revenue and the Company has issued no invoices.', 'Collectible receivables may increase equity value.'],
    ['Tangible assets', 'None of material value as of the Valuation Date. The Company\'s business is software-, content- and community-based.', 'Physical assets may support value if owned by the Company.'],
    ['Identifiable Company-owned IP', `The Platform (the Nosebleed Sports application, the website, the Discord community and the Premium Offering) and related Platform-specific code, repositories, data pipelines, documentation and development materials were built from May 2026 with JGN funding, which is part of the JGN Contribution of ${APPROX_TOTAL}, and are assigned to the Company on the Actual Closing Date through the Founder PIIA and the JGN Agreement, and documented in the IP Assignment Schedule and Chain of Title Register and the Company Account Schedule. The Company does not own the Nosebleed Sports brand or the Social Accounts; it uses the brand under the Brand License. The Platform was in launch stage, had produced no revenue and had not been independently valued.`, 'Company-owned IP supports value only to the extent ownership and chain of title are documented; a licensed brand and a borrowed audience support value less than owned ones.'],
    ['Software development status', `Launch stage. The application, the website and the Discord community were begun by the Chief Executive Officer, the website was refined by the Chief Information Officer, and the Chief Technology Officer was completing all three for launch. The application relied on prototype and non-production data sources and remained subject to final testing, licensed-data-provider selection, app-store distribution, security, deployment, onboarding and commercialization work. The Platform had not established any commercial operating history or verified subscriber demand.`, 'Stage of development affects risk-adjusted value.'],
    ['Cost to date', `${APPROX_TOTAL} from May through November 2026, all paid by JGN: ${HIST.map(h => (h.cat.startsWith('AI') ? h.cat : h.cat.charAt(0).toLowerCase() + h.cat.slice(1)) + ' ' + money(h.amount)).join('; ')}, as itemized in the Historical Company Operating Expense and JGN Contribution Schedule.`, 'For a pre-revenue product, documented cost is the most reliable evidence of value.'],
    ['Liabilities and accrued obligations', 'None owed to JGN or to any Member for the historical expenses, which are Capital Contributions and not loans. The Company\'s share of obligations under the Talent Agreement is funded by JGN until the Self-Sufficiency Date.', 'Liabilities reduce equity value to the extent outstanding and properly booked.'],
    ['Operating history', `Limited organizational and development-stage history: Platform development from May 2026, formation on ${FORMED}, EIN assignment on August 17, 2026, and the Talent Agreement effective ${TALENT_DATE}. The Company had not begun commercial operations as of the Valuation Date.`, 'Short or limited operating history generally increases risk.'],
    ['Revenue status', 'None. The app, the website and the Discord community have generated no revenue. All revenue of the Nosebleed Sports brand to date came from the Social Accounts and belongs to JGN. The Company is pre-revenue and dependent on JGN funding.', 'The absence of revenue means value cannot be supported by earnings.'],
    ['Signed customer contracts', 'None. No sponsorship, affiliate or other commercial agreement relates to the Platform.', 'Binding contracts may support value if assignable and collectible.'],
    ['Outside financing', 'None. The Company had not completed or received any outside equity, debt or institutional financing and had no binding financing commitment as of the Valuation Date other than JGN\'s funding commitment under the JGN Agreement, which JGN may end on notice.', 'Financing may affect valuation if closed or binding.'],
    ['Third-party equity offers', 'None. The Company had received no bona fide third-party offer to purchase Company equity, acquire the Company or establish an independent valuation as of the Valuation Date.', 'Bona fide offers may be valuation evidence.'],
    ['Marketability and transfer restrictions', 'Units are illiquid and subject to transfer restrictions, vesting and repurchase rights.', 'Illiquidity and restrictions affect value.'],
    ['Regulatory and execution risk', 'The Premium Offering will sell sports betting picks and analysis, an activity that is regulated or restricted in some states and on some platforms (advertising, age and jurisdiction limits, affiliate and tout rules). The Company remained subject to substantial early-stage execution and commercialization risks, including completion and testing of the Platform; licensed data for production; app-store approval; cybersecurity, privacy and data-protection compliance; migration and control of repositories, infrastructure and Company Accounts; completion and enforceability of IP assignments and the Brand License; dependence on JGN for the brand, the audience and funding; dependence on the Class B Member as the public face of the brand; subscriber acquisition and churn; competition from established picks services and sports apps; pricing uncertainty; reliance on third-party data, hosting, payment and community providers; and limited operating capital.', 'Early-stage execution and regulatory risk reduce certainty of future value.'],
    ['Dependence on Founders, JGN and talent', 'Company value materially depends on Founder execution, continued service and IP cooperation, on JGN\'s Brand License, promotion covenant and funding, and on the Class B Member\'s continued services.', 'Dependence increases risk.'],
    ['Market for Units', 'No public or private trading market for the Units is known.', 'Lack of marketability affects value.'],
    ['Contradictory facts', `No undisclosed contradictory facts are known after reasonable review of the Company's records as of the Valuation Date. The Members specifically considered: the built but launch-stage Platform; the absence of any revenue, customer, bank account or financing; the cost of ${APPROX_TOTAL}; the licensed rather than owned brand and audience; the Talent Agreement obligations; and the regulatory character of paid picks. The Members considered those facts together and concluded in good faith that the Company is worth no more than the documented cost of forming it and building the Platform. If any material revenue, signed contract, financing, acquisition proposal, third-party equity offer, material asset, liability or other valuation-relevant fact existed as of the Valuation Date but was not disclosed in this memorandum, the valuation must be reconsidered before the Units are issued on the Actual Closing Date.`, 'Contradictory facts must be resolved before the Units are issued on the Actual Closing Date.'],
  ], 'w3') +
  `<h2>3. GOOD-FAITH VALUATION FACTORS</h2>
<p>The total company equity Fair Market Value of ${APPROX_TOTAL} reflects the Company's actual condition on the Valuation Date, including a built but launch-stage Platform; no cash; no revenue; no customers or commercial contracts; a brand and audience that the Company licenses and borrows rather than owns; no outside financing; no bona fide third-party equity or acquisition offers; no proven commercial adoption; no established product-market fit; limited operating history; material Founder, JGN and talent dependence; unresolved regulatory, commercialization and execution risk; restricted and illiquid Units; vesting and Company repurchase rights; and the need to complete Company Account migration.</p>
<p>The Members considered the totality of the Company's qualitative and quantitative valuation factors and exercised good-faith business judgment. They used the documented cost of forming the Company and building the Platform because no revenue, earnings, financing, offer or comparable transaction exists from which any other value could be derived.</p>
<ul>
<li>The Company is a launch-stage Delaware LLC whose Units are held by its five Founders and one Class B Member.</li>
<li>The Units are illiquid, privately held and subject to transfer restrictions, vesting, repurchase rights and member-governance controls.</li>
<li>The Company depends materially on Founder service, Founder IP assignments, Company Account control, the JGN Agreement (Brand License, promotion covenant and funding) and the Talent Agreement.</li>
<li>The record book does not include audited financial statements, binding third-party valuations, closed institutional financing, committed recurring revenue or signed acquisition offers.</li>
<li>The Company may not rely on this conclusion if actual Valuation Date facts contradict the completed worksheet.</li>
</ul>
<h2>4. CONCLUSION</h2>
<p>Based on the facts documented in this memorandum, the Members determine in good faith that the total company equity Fair Market Value as of the Valuation Date equals the aggregate JGN Contribution through that date, ${APPROX_TOTAL}. Because the Operating Agreement returns that same amount of Unreturned Capital to the Contributing Founders before any other distribution, a sale of the Company's assets for their Fair Market Value on the Valuation Date followed by a liquidation would return the Contributing Founders' capital and leave nothing for the Service Units, which therefore have no liquidation value on the Valuation Date. The determination is approved solely for the initial issuance and may not be used as a later financing, acquisition, repurchase, litigation, accounting or tax valuation; any such use requires a new determination as of that later date.</p>
<h2>5. MEMBER ACKNOWLEDGMENT</h2>` + memberSigs(() => 'Class A Member');
  return doc(3, 'FOUNDER EQUITY FAIR MARKET VALUE DETERMINATION MEMORANDUM', body);
}

// 04 Founder Capital Contribution Instructions
function doc04() {
  const per = CONTRIB.map(f => `<h3>${f.name}</h3>` + kv([['Class A Units issued', num(f.units)], ['Capital Contribution', APPROX_EACH + ' (25% of ' + APPROX_TOTAL + ')'], ['Made by', CREDIT_FROM], ['Date contribution recorded'], ['Supporting records reference'], ['Receipt Number']], 'kv2')).join('');
  const body = `<p><strong>Effective date:</strong> these instructions are effective on approval of the Initial Member and Organizational Written Consent and govern how each Contributing Founder's Capital Contribution is recorded under Section 3.5 of the Operating Agreement. The per-Founder records below are completed when the Company records each contribution. Under Section 2.8 of the Operating Agreement, the Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date are the same date unless the Operating Agreement is amended under Article 16 to provide otherwise. ${DEFINED}</p>
<p>No Founder purchases Units for cash. No payment is made into a Company account for any Unit, and no promissory notes, purchase prices or deferred-payment rights exist.</p>
<p>Accounting treatment: the JGN Contribution through the Actual Closing Date, ${APPROX_TOTAL}, is the Capital Contribution of the four Contributing Founders, one quarter each, in exchange for their restricted Class A Units. ${SERVICE.name} receives his Class A Units, and Brock Smith his Class B Units, for services as profits interests, and neither makes a Capital Contribution.</p>` +
  kv([['Method', 'Recording of amounts JGN has already paid for the Company and the Platform, as listed in the Historical Company Operating Expense and JGN Contribution Schedule; no new payment'], ['Contribution amount', `${APPROX_EACH} for each of ${CONTRIB_AND}; ${APPROX_TOTAL} in total`], ['Supporting records', 'JGN\'s bank, card and vendor payment records for the listed expenses, made available by the Chief Executive Officer to every Member before signing'], ['Confirmation', 'The Chief Executive Officer compiles the amounts from JGN\'s payment records, and each Contributing Founder confirms them by signing that Founder\'s Restricted Unit Issuance Agreement'], ['True-up', 'Any amount JGN paid for the Company before the Actual Closing Date that is not listed, and that JGN documents to the Members within 60 days after the Actual Closing Date, is added and credited one quarter each (Operating Agreement Section 3.5)'], ['Receipt', 'The Company issues each Contributing Founder a receipt once that Founder\'s contribution is recorded'], ['Accounting', 'Credited to the Founder\'s Capital Account and Unreturned Capital on the Actual Closing Date under Operating Agreement Sections 3.9 and 10.2'], ['Finality', 'Once the Actual Closing Date occurs, a recorded Capital Contribution may not be reduced, refunded, offset or recharacterized except as the Operating Agreement provides. If the contributions lapse under Section 3.6 of the Operating Agreement, no Units are issued.']]) +
  per + coSig();
  return doc(4, 'FOUNDER CAPITAL CONTRIBUTION INSTRUCTIONS', body);
}

// 05 Aggregate Founder Issuance Closing Statement
function doc05() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Units', num(f.units) + ' Class A Units'], ['Fully diluted ownership', fdPct(f.units)], ['Consideration', f.jgn ? 'Capital Contribution made through JGN' : 'Services as Chief Technology Officer, including completing the build of the Platform (profits interest)'], ['Capital Contribution Amount', f.jgn ? APPROX_EACH : 'None'], ['Cash paid for Units', 'None'], [f.jgn ? 'Contribution recorded' : 'Issuance recorded'], ['Immediately Vested', num(vested(f))], ['Restricted Units', num(vested(f))], ['Issuance condition', f.jgn ? 'Execution and recorded Capital Contribution required' : 'Execution required']], 'kv2')).join('');
  const body = EFF + per +
  `<h3>Brock Smith (Class B)</h3>` + kv([['Units', num(CLASS_B) + ' Class B Units'], ['Fully diluted ownership', fdPct(CLASS_B)], ['Consideration', 'Services under the Talent Agreement (profits interest)'], ['Capital Contribution Amount', 'None'], ['Vesting', 'Fully vested on issuance'], ['Issuance condition', 'Talent Amendment signed by JGN, the Company and Brock Smith; Actual Closing Date']], 'kv2') +
  `<h3>Total – all Founders (Class A)</h3>` + kv([['Units', num(CLASS_A) + ' Class A Units'], ['Fully diluted ownership', fdPct(CLASS_A)], ['Aggregate Capital Contribution', APPROX_TOTAL], ['Cash paid for Units', 'None'], ['All contributions recorded'], ['Immediately Vested', num(CLASS_A / 2)], ['Restricted Units', num(CLASS_A / 2)], ['Issuance condition', 'All Founder closings complete']], 'kv2') +
  tbl(['Reconciliation', 'Amount'], [['Aggregate JGN Contribution through the Actual Closing Date', APPROX_TOTAL], ['Aggregate Founder Capital Contributions', APPROX_TOTAL], ['Aggregate capital credited to Members\' Capital Accounts', APPROX_TOTAL], ['Outstanding Units after closing (Class A plus Class B)', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)]], 'keep') +
  `<p>The aggregate JGN Contribution equals the aggregate Founder Capital Contributions and the aggregate capital credited to Members' Capital Accounts. The Service Units add no capital.</p>
<p>The Company shall not mark any issuance complete until the applicable Founder has executed required documents and, for a Contributing Founder, the Company has recorded the applicable Capital Contribution.</p>` + coSig();
  return doc(5, 'AGGREGATE FOUNDER ISSUANCE CLOSING STATEMENT', body);
}

// 06 Founder Capital Contribution Ledger
function doc06() {
  const per = CONTRIB.map(f => `<h3>${f.name}</h3>` + kv([['Units', num(f.units) + ' Class A Units'], ['Capital Contribution Amount', APPROX_EACH], ['Made by', CREDIT_FROM], ['Date contribution recorded'], ['Supporting records reference'], ['Receipt Number'], ['Capital Account Credit', APPROX_EACH], ['Opening Unreturned Capital', APPROX_EACH]], 'kv2')).join('');
  const body = EFF + per +
  `<h3>${SERVICE.name}</h3>` + kv([['Units', num(SERVICE.units) + ' Class A Units'], ['Capital Contribution Amount', 'None; Units issued for services as a profits interest'], ['Capital Account Credit', '$0'], ['Opening Unreturned Capital', '$0']], 'kv2') +
  `<h3>Total – all Founders</h3>` + kv([['Units', num(CLASS_A) + ' Class A Units'], ['Aggregate Capital Contribution', APPROX_TOTAL], ['Date last contribution recorded'], ['Receipt Number Range'], ['Aggregate Capital Account Credit', APPROX_TOTAL], ['Aggregate Unreturned Capital', APPROX_TOTAL]], 'kv2') +
  tbl(['Reconciliation', 'Amount'], [['Aggregate JGN Contribution through the Actual Closing Date', APPROX_TOTAL], ['Aggregate Founder Capital Contributions', APPROX_TOTAL], ['Aggregate capital credited to Members\' Capital Accounts', APPROX_TOTAL]]) +
  `<p>Each Capital Contribution is one quarter of the amounts JGN paid for the Company and the Platform (${money(HIST_TOTAL)} ÷ 4 = ${money(CONTRIB_EACH)}). It adds no cash to the Company. The Class B Member, Brock Smith, makes no contribution and has an opening Capital Account of zero. Final accounting entries and Capital Account credits are recorded in the Company's books and tied to JGN's payment records and the Founder Capital Contribution Receipts.</p>` + coSig();
  return doc(6, 'FOUNDER CAPITAL CONTRIBUTION LEDGER', body);
}

// 07 Company Officer Certificate
function doc07() {
  const body = DEF_ONLY +
  `<p>This certificate is signed after all contribution records, signatures and record updates are complete. The undersigned officer certifies, as of the date signed below, that:</p>
<ul>
<li>the Company recorded each Contributing Founder's Capital Contribution listed in the Aggregate Founder Issuance Closing Statement;</li>
<li>the Company issued ${num(CLASS_A)} Class A Units to the Founders listed on Schedule A of the Operating Agreement and ${num(CLASS_B)} Class B Units to Brock Smith under Section 3.7(b) of the Operating Agreement, and ${num(RESERVE)} Units remain unissued as Reserved Units;</li>
<li>the aggregate JGN Contribution through the Actual Closing Date, the aggregate Founder Capital Contributions and the aggregate capital credited to Members' Capital Accounts each equal ${APPROX_TOTAL}, and no cash was paid for any Unit;</li>
<li>the amounts were compiled from JGN's payment records, which were made available to every Member before signing;</li>
<li>no fact arising after the Members signed the Founder Equity Fair Market Value Determination Memorandum and on or before the Actual Closing Date contradicts it;</li>
<li>the Company's Official Unit Ledger, Capitalization Table, Founder Equity and Vesting Ledger, Founder Capital Contribution Ledger and Members' Capital Accounts have been updated;</li>
<li>the Company delivered to Brock Smith a copy of the Operating Agreement and the Class B Unit Issuance Record, or will do so within 10 days after the Actual Closing Date;</li>
<li>the Company retained signed copies of the Operating Agreement, the Initial Member and Organizational Written Consent, the five Restricted Unit Issuance Agreements, the Founder PIIA, the JGN Agreement, the JGN Member Consent Approving Nosebleed Agreement, the Class B Unit Issuance Record, the First Amendment to the Talent Agreement and the Founder Capital Contribution Receipts, and a copy of the Talent Agreement.</li>
</ul>` +
  kv([['Actual Closing Date'], ['Last contribution recorded'], ['Receipt Number Range'], ['Supporting records reference'], ['Aggregate Capital Contributions', APPROX_TOTAL], ['Aggregate capital credited to Members\' Capital Accounts', APPROX_TOTAL], ['Founder Capital Contribution Ledger updated'], ['Official Unit Ledger updated'], ['Capitalization Table updated'], ['Founder Equity and Vesting Ledger updated'], ['Members\' Capital Accounts updated']], 'kv keep') +
  coSig();
  return doc(7, 'COMPANY OFFICER CERTIFICATE – FOUNDER EQUITY CLOSING', body, { coverTitle: 'COMPANY OFFICER CERTIFICATE&nbsp;– FOUNDER EQUITY CLOSING', h1: CO_UP + ' COMPANY OFFICER CERTIFICATE&nbsp;– FOUNDER EQUITY CLOSING' });
}

// 08 Officer Appointment Record
function doc08() {
  const body = DEF_ONLY +
  `<p>This officer record is adopted under Resolution 11 of the Initial Member and Organizational Written Consent, effective upon approval of that consent, and continues in effect under the Operating Agreement on and after the Actual Closing Date. Spending thresholds are measured per vendor, engagement or related series of payments in any rolling 12-month period, as Operating Agreement Section 4.3 provides. An expense to be funded by JGN also requires JGN's funding approval under the JGN Agreement.</p>` +
  tbl(['Officer', 'Title', 'Core ordinary-course lane'], FOUNDERS.map(f => [nbName(f), `${f.office} ("${f.short}")`, f.lane]), 'w') +
  `<p>Brock Smith, the Class B Member, holds no office and provides services as an independent contractor under the Talent Agreement.</p>` +
  tbl(['Authority area', 'Approved authority'], [
    ['CEO ordinary-course spending', 'Up to $5,000 individually without separate approval.'],
    ['Other officer ordinary-course spending', 'Up to $2,000 within the officer\'s lane without separate approval.'],
    ['Other officer spending over $2,000 and up to $5,000', 'Requires the CEO\'s approval.'],
    ['Any spending over $5,000 and up to $25,000', 'Requires approval of the CEO and at least two additional Founders then in Continuous Service.'],
    ['Any spending above $25,000', 'Requires Supermajority Approval in every case.'],
    ['Major Decisions', 'Must be approved under the Operating Agreement and cannot be taken by officer action alone.'],
    ['Banking', 'The CEO is the Company\'s sole authorized signer on its bank accounts (Banking Resolution).'],
  ], 'keep') + coSig();
  return doc(8, 'OFFICER APPOINTMENT RECORD AND AUTHORITY CERTIFICATE', body);
}

// 09 Banking Resolution
function doc09() {
  const body = DEF_ONLY +
  `<p>The following banking resolution was approved by the Members under Resolution 11 of the Initial Member and Organizational Written Consent, effective upon approval of that consent, and continues in effect under the Operating Agreement on and after the Actual Closing Date.</p>
<p>1. Opening of Bank Account. The Company has no bank account as of the date of this resolution. ${CEO.name}, as Chief Executive Officer (the "Authorized Banking Officer"), is authorized and directed to open a business checking account in the Company's legal name, ${CO}, under EIN ${EIN}, at ${BANK}, and may open additional savings, card, merchant, payment-processor and related financial accounts in the Company's legal name. The last four digits of each account number are recorded in the Company Account Schedule when the account is opened; no full account number appears in the record book. Opening the account is not a condition of the Actual Closing Date, because no Founder pays cash for Units.</p>
<p>2. Sole Signer. The Authorized Banking Officer is the Company's sole authorized signer and is authorized to work with financial institutions and payment processors to open, maintain, access and administer Company accounts, subject to the Operating Agreement. He may sign for the Company within the spending authority in Operating Agreement Section 4.3. If he is unable to act under Operating Agreement Section 4.8 or ceases to be Chief Executive Officer, the acting Chief Executive Officer under that Section is the Authorized Banking Officer until he resumes the office under that Section or the Members designate a successor by Supermajority Approval, and the bank may rely on a certificate signed by any two Founders stating who is then the Authorized Banking Officer under Operating Agreement Section 4.8 and that any determination or confirmation that Section requires has been made.</p>
<p>3. Founder Access. Each other Founder in Continuous Service is entitled to view-only access to the Company's bank accounts and statements, through the bank's online tools where available and otherwise by copies the Authorized Banking Officer provides on request. View access carries no authority to sign, pay, transfer or withdraw.</p>
<p>4. JGN Contributions and Platform Revenue. Amounts JGN pays into the Company's account under the JGN Agreement are recorded as JGN Contributions. Subscription, membership and other Platform revenue is collected directly into accounts in the Company's own name and is not collected by JGN, as the JGN Agreement provides.</p>
<p>5. No Expansion of Spending Authority. This resolution does not override, waive or expand the spending thresholds, budget rules, Major Decision approvals, related-party controls, debt approvals or Supermajority Approval requirements in the Operating Agreement.</p>
<p>6. Access Controls. Company financial accounts shall use Company-controlled email, MFA, password-manager controls and record retention sufficient for tax, audit, diligence and acquisition review.</p>` + coSig();
  return doc(9, 'BANKING RESOLUTION', body);
}

// 10 Official Unit Ledger
function doc10() {
  const per = FOUNDERS.map(f => `<h3>${f.id} — ${f.name}</h3>` + kv([['Entry ID', f.id], ['Issuance date', 'Actual Closing Date'], ['Class', f.jgn ? 'Class A Units' : 'Class A Units (Service Units; profits interest)'], ['Units', num(f.units)], ['Percentage Interest', outPct(f.units)], ['Voting Interest', votePct(f.units)], ['Fully Diluted Percentage', fdPct(f.units)], ['Consideration', f.jgn ? 'Capital Contribution through JGN, ' + APPROX_EACH : 'Services; no Capital Contribution'], ['Vesting Status', '50% vested; 50% restricted'], ['Original Cost', f.jgn ? 'Unreturned Capital divided by Class A Units held, at the time of a repurchase' : 'Zero'], ['Certificate Status', 'Uncertificated book-entry interest']], 'kv2')).join('');
  const brock = `<h3>${BROCK.id} — ${BROCK.name}</h3>` + kv([['Entry ID', BROCK.id], ['Issuance date', 'Actual Closing Date'], ['Class', 'Class B Units (non-voting Service Units; profits interest)'], ['Units', num(BROCK.units)], ['Percentage Interest', outPct(BROCK.units)], ['Voting Interest', 'None'], ['Fully Diluted Percentage', fdPct(BROCK.units)], ['Consideration', 'Services under the Talent Agreement; no Capital Contribution'], ['Issued under', 'Operating Agreement Section 3.7(b); Talent Agreement Section 5.1 as amended (Initial Units)'], ['Vesting Status', 'Fully vested on issuance'], ['Original Cost', 'Zero'], ['Certificate Status', 'Uncertificated book-entry interest']], 'kv2');
  const reserve = `<h3>Reserved Units</h3>` + kv([['Status', 'Authorized and unissued'], ['Units', num(RESERVE)], ['Fully Diluted Percentage', fdPct(RESERVE)], ['Purpose', 'Future strategic partners (Operating Agreement Section 3.13) and Milestone Units under the Talent Agreement (Operating Agreement Section 3.7(b))'], ['Issuance', 'Strategic-partner issuances require Supermajority Approval as a Major Decision and the consent required by Operating Agreement Section 5.7; Milestone Units are issued when earned'], ['Rights', 'None until issued; not counted in any threshold']], 'kv2');
  const body = EFF + per + brock + reserve +
  tbl(['Summary', 'Units'], [['Class A Units issued', num(CLASS_A)], ['Class B Units issued', num(CLASS_B)], ['Outstanding Units', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)], ['Authorized Units', num(AUTH_UNITS)]]) +
  `<p class="note">Ledger note: all issued Class A Units vote and participate in distributions and tax allocations whether vested or unvested, subject to Operating Agreement Section 7.5 in a Change of Control. Vesting affects only the Company's contractual repurchase right, related recordkeeping and the timing of, and entitlement to, consideration under Section 7.5 of the Operating Agreement. Class B Units do not vote. Every distribution first returns Unreturned Capital to the Contributing Founders and is then shared by all outstanding Units pro rata (Operating Agreement Section 10.5).</p>` + coSig();
  return doc(10, 'OFFICIAL UNIT LEDGER', body);
}

// 11 Capitalization Table
function doc11() {
  const rows = FOUNDERS.map(f => [nbName(f), f.office, 'A', num(f.units), outPct(f.units), votePct(f.units), fdPct(f.units)]);
  rows.push([nbName(BROCK), 'Co-Founder', 'B', num(BROCK.units), outPct(BROCK.units), 'None', fdPct(BROCK.units)]);
  rows.push(['Reserved Units', 'Unissued', '', num(RESERVE), 'Not outstanding', 'Not outstanding', fdPct(RESERVE)]);
  rows.push(['<strong>Total</strong>', '', '', '<strong>' + num(AUTH_UNITS) + '</strong>', '<strong>100%</strong>', '<strong>100%</strong>', '<strong>100%</strong>']);
  const rows2 = FOUNDERS.map(f => [nbName(f), num(f.units), f.jgn ? APPROX_EACH : 'None', f.jgn ? 'Capital Contribution through JGN' : 'Services; profits interest', num(vested(f)), num(vested(f))]);
  rows2.push([nbName(BROCK), num(BROCK.units), 'None', 'Services; profits interest', num(BROCK.units), 'None']);
  rows2.push(['<strong>Total issued</strong>', '<strong>' + num(OUTSTANDING) + '</strong>', '<strong>' + APPROX_TOTAL + '</strong>', '', '<strong>' + num(CLASS_A / 2 + CLASS_B) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>']);
  const body = DEF_ONLY +
  `<p>Fully diluted capitalization treats the ${num(RESERVE)} Reserved Units as issued. No options, warrants or convertible securities exist. The only equity commitment other than the issued Units is the Milestone Units under the Talent Agreement, which, if earned, are issued from the Reserved Units up to a cumulative 5% fully diluted interest for Brock Smith (including his Class B Units).</p>` +
  tbl(['Member', 'Title', 'Class', 'Units', 'Outstanding % (of ' + num(OUTSTANDING) + ')', 'Voting % (of ' + num(CLASS_A) + ' Class A)', 'Fully diluted % (of ' + num(AUTH_UNITS) + ')'], rows) +
  tbl(['Member', 'Units', 'Capital Contribution', 'Consideration', 'Vested at closing', 'Unvested'], rows2) +
  kv([['Total company equity FMV as of Transfer Date', APPROX_TOTAL], ['Aggregate Unreturned Capital, returned first on any distribution', APPROX_TOTAL], ['Cash paid for Units', 'None'], ['Equity incentive pool', 'None; the Reserved Units are reserved for strategic partners and Milestone Units'], ['Interest types', 'Contributing Founders: Class A Units issued for Capital Contributions. Service Founder: Class A profits interest. Class B Member: non-voting profits interest.'], ['Not a future valuation', 'The total equity FMV is for the Founder issuance date only, not a financing, enterprise-value or acquisition valuation.']]) + coSig();
  return doc(11, 'CAPITALIZATION TABLE', body);
}

// 12 Founder Equity and Vesting Ledger
function doc12() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Issued Units', num(f.units) + ' Class A Units'], ['Consideration', f.jgn ? 'Capital Contribution through JGN, ' + APPROX_EACH : 'Services; no Capital Contribution'], ['Original Cost', f.jgn ? 'Unreturned Capital divided by Class A Units held, at the time of a repurchase' : 'Zero'], ['Immediately Vested Units', num(vested(f))], ['Restricted Units', num(vested(f))], ['Monthly Vesting Amount', `${num(monthly(f))} Units per month (${num(vested(f))} divided by 48, rounded down), final installment trued up under Operating Agreement Section 6.2`]], 'kv2')).join('');
  const body = DEF_ONLY +
  `<p>The vesting commencement date is the Actual Closing Date. 50% of each Founder's issued Class A Units vest immediately. The remaining 50% vest in 48 equal monthly installments, subject to Continuous Service and the Operating Agreement.</p>` + per +
  `<h3>Brock Smith (Class B)</h3>` + kv([['Issued Units', num(CLASS_B) + ' Class B Units'], ['Consideration', 'Services under the Talent Agreement; no Capital Contribution'], ['Original Cost', 'Zero'], ['Vesting', 'Fully vested on issuance (Talent Agreement Section 5.1 as amended; Operating Agreement Section 6.16).'], ['Milestone Units', 'Earned only as Talent Agreement Sections 5.2, 5.5 and 5.9 provide.']], 'kv2') +
  `<p class="note">Rounding note: monthly installments are rounded down to whole Units as shown above, and the rounding difference vests in the final (48th) installment under Operating Agreement Section 6.2.</p>
<p class="note">Sale note: if a buyer, the Company or their Affiliates end a Founder's Continuous Service without Cause at or after a Change of Control, the Founder resigns for Good Reason, the buyer does not keep the Founder on, or the Founder dies or has a Disability after the Change of Control, 100% of that Founder's unvested Units vest and the full amount held for them is paid (Operating Agreement Section 6.12).</p>
<p class="note">Departure note: unvested Class A Units remain subject to automatic repurchase at the lower of their total Original Cost and their Fair Market Value, which for the Service Founder is no consideration, unless a higher price is required by signed agreement or law. Vested Units are not subject to repurchase at Original Cost; they remain subject to the Fair Market Value call options under Operating Agreement Sections 6.8 (Bad Leaver), 6.13 (voluntary departure other than as a Good Leaver, or termination for Cause) and 6.15 (competition), transfer restrictions and the other rights expressly set forth in the Operating Agreement. Monthly vesting is suspended during an uncured default under Operating Agreement Section 6.14, with the schedule extended by the suspended months.</p>` + coSig();
  return doc(12, 'FOUNDER EQUITY AND VESTING LEDGER', body);
}

// 13 Founder Contribution and Separation Schedule
function doc13() {
  const role = { 'Nicholas Restivo': 'Conceived the app, the website and the Discord community and began building them before the Actual Closing Date.', 'Christian Clark': 'Brought in to complete the app, the website and the Discord community for launch and to serve as Chief Technology Officer.', 'Stephen Bickel': 'Refined the website before the Actual Closing Date.', 'Gabriel DiDario': 'Worked on the Platform before the Actual Closing Date using a development subscription paid by JGN.', 'Michael Del Bene': 'No specific pre-closing Platform development is recorded for this Founder.' };
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([
    ['Capital Contribution', f.jgn ? `${APPROX_EACH}, being 25% of the ${APPROX_TOTAL} JGN paid for the Company and the Platform, made through JGN under Operating Agreement Sections 3.4, 3.5 and 3.9. No cash is paid for Units.` : 'None. This Founder paid no Company or Platform expense and makes no Capital Contribution. His Class A Units are issued for services as a profits interest under Operating Agreement Section 3.7(a).'],
    ['Separate IP and Founder obligations', 'Founder PIIA, IP assignment, confidentiality, invention assignment, data-security, Founder duties and restrictive-covenant obligations remain separately enforceable.'],
    ['Services', role[f.name] + ' Services performed for the Platform before the Actual Closing Date create no claim for compensation, reimbursement or additional Units (Operating Agreement Section 3.8); the resulting work product is assigned under the Founder PIIA and, to the extent JGN owned or controlled it, the JGN Agreement.'],
    ['Founder Advances / reimbursable expenses', 'None. No historical Company operating expense was paid by this Founder personally.'],
    ['JGN interest', f.jgn ? 'Member of JGN Media LLC (25%), disclosed under Schedule D of the Operating Agreement.' : 'None. Not a member of JGN Media LLC and has no right to participate in JGN\'s decisions.'],
    ['Other contributions', 'Any future non-equity contribution, advance, reimbursement, loan or capital call must be separately documented and approved if material.'],
  ], 'kv2')).join('');
  const body = DEF_ONLY +
  `<p>This schedule distinguishes among the Capital Contributions made through JGN, the Service Units issued for services, separate IP and Founder obligations, and other Company contributions.</p>` + per +
  `<h3>Brock Smith (Class B Member)</h3>` + kv([
    ['Class B Units', `${num(CLASS_B)} Class B Units issued under Operating Agreement Section 3.7(b) as the Initial Units under Talent Agreement Section 5.1, as amended, fully vested, as a profits interest; no purchase price; no Capital Contribution.`],
    ['Services', 'Handicapping, content, live-session, community and brand-representation services under the Talent Agreement, compensated by the Monthly Fee, bonuses, revenue shares and the equity in Section 5 of the Talent Agreement.'],
    ['IP', 'Work Product relating to the Platform and the Premium Offering is assigned to the Company, and Work Product relating to the Brand and the Managed Accounts to JGN, under Talent Agreement Section 8.1.'],
    ['Milestone Units', 'Issued from the Reserved Units when earned under Talent Agreement Section 5.2, up to a cumulative 5% fully diluted interest.'],
    ['Other', 'No other equity, contribution, advance or claim.'],
  ], 'kv2') +
  `<p>No Founder duty, IP assignment, service, Founder Advance, reimbursement claim or vendor charge is a Capital Contribution other than the JGN Contribution credited to the Contributing Founders. Future Founder funding of Company expenses must be separately documented as a future capital call, capital contribution agreement, loan or Founder Advance, and JGN funding is governed by the JGN Agreement.</p>` + coSig();
  return doc(13, 'FOUNDER CONTRIBUTION AND SEPARATION SCHEDULE', body);
}

module.exports = { doc00, doc02, doc03, doc04, doc05, doc06, doc07, doc08, doc09, doc10, doc11, doc12, doc13 };
